echo "Hello from $0 on $(hostname)"

#!/bin/zsh
# usage: opts.zsh [-v] [-n count] file...
count=1 verbose=0
while getopts ":n:vh" opt; do
  case $opt in
    n) count=$OPTARG ;;
    v) verbose=1 ;;
    h) echo "usage: ${0:t} [-v] [-n count] file..."; exit 0 ;;
    :) echo "option -$OPTARG needs a value" >&2; exit 2 ;;
    \?) echo "unknown option -$OPTARG" >&2; exit 2 ;;
  esac
done
shift $(( OPTIND - 1 ))
echo "count=$count verbose=$verbose files: $@"

#!/bin/zsh
# netcheck.zsh - one-screen network health report for macOS
# Usage: netcheck.zsh [-q] [-n] [-d domain] [-u url]
setopt PIPE_FAIL NO_UNSET
zmodload zsh/datetime               # gives $EPOCHREALTIME (seconds, with decimals)

domain=example.com
url=https://example.com
quiet=0 color=1 fails=0
iface= myip= gw=
prog=${0:t}                         # script name, captured before any function runs

usage() {
  print -u2 "usage: $prog [-q] [-n] [-d domain] [-u url]"
  exit ${1:-2}
}

while getopts ":qnd:u:h" opt; do
  case $opt in
    q) quiet=1 ;;
    n) color=0 ;;
    d) domain=$OPTARG ;;
    u) url=$OPTARG ;;
    h) usage 0 ;;
    *) usage ;;
  esac
done
shift $(( OPTIND - 1 ))

if [[ -t 1 && $color -eq 1 ]]; then
  c_ok=$'\e[32m' c_bad=$'\e[31m' c_off=$'\e[0m'
else
  c_ok= c_bad= c_off=
fi

pass() { (( quiet )) || printf '%s[ OK ]%s %-24s %s\n' "$c_ok" "$c_off" "$1" "$2" }
fail() { printf '%s[FAIL]%s %-24s %s\n' "$c_bad" "$c_off" "$1" "$2"; (( ++fails )) }

