#!/bin/zsh
name=world upper=0 prog=${0:t}
usage() { print -u2 "usage: $prog [-n NAME] [-u] [-h]"; exit ${1:-2}; }
while getopts ":n:uh" opt; do
  case $opt in
    n) name=$OPTARG ;;
    u) upper=1 ;;
    h) usage 0 ;;
    *) usage ;;
  esac
done
msg="hello, $name"
(( upper )) && msg=${(U)msg}
print -r -- $msg

#!/bin/zsh
PS3="choose> "
select item in time whoami uptime quit; do
  case $item in
    time) date +%T ;;
    whoami) whoami ;;
    uptime) uptime ;;
    quit) break ;;
    *) echo "invalid choice" ;;
  esac
done

#!/bin/zsh
setopt ERR_EXIT NO_UNSET
log=${1:?usage: rotate.zsh LOGFILE KEEP}
keep=${2:-5}
[[ -f $log ]] || { print -u2 "no such file: $log"; exit 1 }
rm -f $log.$keep
for ((i = keep - 1; i >= 1; i--)); do
  [[ -f $log.$i ]] && mv $log.$i $log.$((i + 1))
done
mv $log $log.1
: > $log
